import pandas as pd
import numpy as np

# Load data
data = pd.read_csv('chunks_csv/moran_local_2021_ghg.csv')
adjacency = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Handle missing values
data_points_used = data.shape[0]
data = data.dropna(subset=['GHG_value'])
adjacency = adjacency.dropna(subset=['borough', 'neighbor'])

# Compute neighborhood GHG values
neighborhood_values = {}
for index, row in adjacency.iterrows():
    borough = row['borough']
    neighbor = row['neighbor']
    if borough not in neighborhood_values:
        neighborhood_values[borough] = []
    neighborhood_values[borough].append(data.loc[data['borough'] == neighbor, 'GHG_value'].values[0])

# Compute average neighborhood GHG values
neighborhood_values = {borough: np.mean(neighbors) for borough, neighbors in neighborhood_values.items()}

# Identify hot and cold spots
hot_spots = []
cold_spots = []
for index, row in data.iterrows():
    borough = row['borough']
    ghg_value = row['GHG_value']
    if borough in neighborhood_values:
        avg_neighbor_ghg = neighborhood_values[borough]
        if ghg_value > avg_neighbor_ghg:
            hot_spots.append((borough, ghg_value, avg_neighbor_ghg))
        elif ghg_value < avg_neighbor_ghg:
            cold_spots.append((borough, ghg_value, avg_neighbor_ghg))

# Compute statistical method (Moran's I)
def moran_i(ghg_values, neighborhood_values):
    n = len(ghg_values)
    sum = 0
    for i in range(n):
        for j in range(i+1, n):
            sum += (ghg_values[i] - np.mean(ghg_values)) * (ghg_values[j] - np.mean(ghg_values))
    return sum / (n * (n-1) * np.var(neighborhood_values))

# Perform permutation test
def permutation_test(hot_spots, cold_spots, num_permutations=500):
    test_statistics = []
    for _ in range(num_permutations):
        hot_spots_perm = hot_spots.copy()
        cold_spots_perm = cold_spots.copy()
        np.random.shuffle(hot_spots_perm)
        np.random.shuffle(cold_spots_perm)
        test_statistics.append(moran_i([hs[1] for hs in hot_spots_perm], [cs[2] for cs in cold_spots_perm]))
    test_statistics.sort()
    p_value = np.mean([ts <= moran_i([hs[1] for hs in hot_spots], [cs[2] for cs in cold_spots]) for ts in test_statistics])
    return p_value

# Identify final hot and cold spots
p_value = permutation_test(hot_spots, cold_spots)
for hs in hot_spots:
    if moran_i([hs[1]], [neighborhood_values[hs[0]]]) < p_value:
        print(f"FINAL ANSWER: {hs[0]} (HH, statistical method={moran_i([hs[1]], [neighborhood_values[hs[0]])})")
for cs in cold_spots:
    if moran_i([cs[1]], [neighborhood_values[cs[0]]]) < p_value:
        print(f"FINAL ANSWER: {cs[0]} (LL, statistical method={moran_i([cs[1]], [neighborhood_values[cs[0]]])})")
if not hot_spots and not cold_spots:
    print("FINAL ANSWER: none")
